import{_ as i,l as n,o as e,c as s,v as o,p as l,x as t,d as p,i as h,S as C}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"紧凑模型对严格电磁","description":"","frontmatter":{"title":"紧凑模型对严格电磁","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/compact-vs-rigorous.md","filePath":"litho/compact-vs-rigorous.md","lastUpdated":1789023840000}'),c={name:"litho/compact-vs-rigorous.md"};function d(D,a,T,m,A,f){const r=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="紧凑模型对严格电磁" tabindex="-1">紧凑模型对严格电磁 <a class="header-anchor" href="#紧凑模型对严格电磁" aria-label="Permalink to &quot;紧凑模型对严格电磁&quot;">​</a></h1><div class="epigraph"><p>全芯片要的是可重复的前向；掩模开口要的是麦克斯韦边值。紧凑模型把后者收成可调用的核，严格电磁只在核会撒谎的地方出场。</p><footer>—— 对照 Wong 对 Hopkins / TCC 成像的表述，以及 Erdmann 对紧凑掩模模型与 FDTD、波导 / RCWA 的对照</footer></div><p><a href="/litho/dtco-patterning">上一课</a>把设计规则、单元和工艺窗收进同一条 DTCO 环，前向默认是能每晚跑完全场的紧凑模型。缺口是：薄屏 Kirchhoff 加 <a href="/litho/hopkins-tcc">Hopkins TCC</a> 在开口尺度接近波长、斜入射和偏振都进预算时，系统误差会被 OPC 修进错误的边。本课钉紧凑与严格电磁各回答什么。胶图形如何变成硬掩模与硅，留给<a href="/litho/rie-pattern-transfer">下一课</a>，不要在这里开始写腔体化学。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DTCO 与模型基 <a href="/litho/opc">OPC</a> 共享同一类前向：照明与瞳收成 TCC，掩模是平面透过率，胶与刻蚀是阈值、高斯模糊和密度偏置。全芯片变量数只允许这种复杂度。上一课把「可制造」写成在这个前向上关窗；若前向漏掉 <a href="/litho/mask-3d-effect">掩模 3D</a> 的阴影、HV 偏置和最佳焦漂，关窗是假的。</p><p>严格方法对局部几何解麦克斯韦：时域有限差分（FDTD）、严格耦合波 / 波导法（RCWA）。它们给出衍射级的振幅、相位与偏振，而不是乘一个 \\(t\\)。代价是不能对全芯片每个边现场求解。缺口因此是分工，不是选一个「更物理」的冠军。</p><h3 id="tcc-不是麦克斯韦的反义词" tabindex="-1">TCC 不是麦克斯韦的反义词 <a class="header-anchor" href="#tcc-不是麦克斯韦的反义词" aria-label="Permalink to &quot;TCC 不是麦克斯韦的反义词&quot;">​</a></h3><p>Hopkins 把部分相干强度写成物体频谱的双线性型，TCC 是照明与两个错位投影瞳的重叠。Wong 的投影成像教材把这条链写成可计算的核：光源与镜头固定则 TCC 可预计算，掩模只进频谱。紧凑的含义是<strong>掩模近场被压缩</strong>，不是光学变成几何光学。Erdmann 的对照是：在 hyper-NA 与厚吸收体上，先用 FDTD / 波导得到近场，再校准边界层、频谱滤波或 Jones 瞳一类紧凑修正，让全芯片仍走 TCC 路径。</p><p><span class="marginnote">把「紧凑」理解成「不严谨」会写错合同。量产 OPC 的紧凑模型必须对校准过的图形族可重复；严格电磁是校准源，不是每晚的求解器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工业分层通常是：代表性夹与热区用 FDTD 或 RCWA 建库；全芯片用 Hopkins / 和差相干分解，叠上库里的 M3D 修正和紧凑胶核。Wong 给出薄屏加 TCC 何时够用：特征远大于波长、正入射、标量。Erdmann 评估波导与 FDTD 对浸没高 NA 的工艺窗与 through-pitch，强调比近场切片更要看窗和偏置。</p><p>校准必须声明照明、膜系与偏振。换吸收体厚度或换偶极，库要重算。AI 替代近场可以降成本，外推到未见过的二维拐角时，仍要以严格夹为闸。</p>',12)),(e(),l(C,null,{default:t(()=>[h(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TCC%5B%22Hopkins%20TCC%20%2F%20%E8%96%84%E5%B1%8F%22%5D%20--%3E%20CHIP%5B%22%E5%85%A8%E8%8A%AF%E7%89%87%20OPC%20%2F%20DTCO%22%5D%0A%20%20FDTD%5B%22FDTD%20%2F%20RCWA%20%E8%BF%91%E5%9C%BA%22%5D%20--%3E%20LIB%5B%22M3D%20%E5%BA%93%20%2F%20%E7%B4%A7%E5%87%91%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20LIB%20--%3E%20CHIP%0A%20%20CHIP%20--%3E%20CLIP%5B%22%E7%83%AD%E5%8C%BA%E5%86%8D%E4%B8%A5%E6%A0%BC%E5%A4%8D%E6%A0%B8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="胶核仍是紧凑的" tabindex="-1">胶核仍是紧凑的 <a class="header-anchor" href="#胶核仍是紧凑的" aria-label="Permalink to &quot;胶核仍是紧凑的&quot;">​</a></h3><p>即使掩模近场改严格，抗蚀剂在 OPC 里仍是阈值与扩散，不是分子动力学。上一课 DTCO 关的窗，纵轴仍是这套紧凑 CD。严格电磁修正的是进入胶之前的空中像；它不自动给出 <a href="/litho/euv-stochastics">随机缺孔</a>。把 FDTD 空中像直接当良率，会漏掉胶与刻蚀两段。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>薄屏把开口当成无限薄复透过率，衍射级由傅里叶变换一次给出。厚掩模是波导：开口内传播常数随偏振与宽度变，左右边对斜入射不等价。FDTD 吃任意三维，耗内存与时间；RCWA 吃周期性或可周期延拓的膜堆，对线栅和接触孔阵列更自然。紧凑修正把「级振幅相对 Kirchhoff 的差」做成滤波或边界层，使 TCC 的双线性型仍可用。</p><p>这解释了为何 DTCO 不能只在设计规则手册里加减间距：若紧凑核没吃进 M3D，规则是在错误空中像上关的。也解释了为何不能全场 FDTD：变量在多边形边上，求解器在体网格上，数量级对不上。</p><p><span class="marginnote">EUV 斜入射阴影是同一分工的极端：薄屏必错，全芯片仍不能现场麦克斯韦。量产靠的是预计算近场加紧凑成像，不是把 OPC 改写成 FDTD 作业。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在没有厚掩模校准的偶极上对二维逻辑做全芯片 ILT 并宣称窗已关闭。不要把某一热区 FDTD 的 CD 差写成节点良率。本课不重写 TCC 积分，那是部分相干课与 Hopkins 专篇的对象。也不把某种商业「M3D 开关」写成已经等于麦克斯韦。</p><p>严格电磁不修复套刻，不抬 NA。它只阻止计算光刻在错误的前向上收敛。下一课的反应离子刻蚀才是把浮雕变成衬底的物理转移；OPC 里的刻蚀偏置仍是紧凑项，不要和腔体里的离子与自由基混名。</p><p><span class="marginnote">出处：A. K. Wong, <em>Optical Imaging in Projection Microlithography</em>（SPIE）；A. Erdmann 等对 FDTD / 波导与紧凑掩模模型的 SPIE 与 JM3 公开对照。不引用未公开的全芯片 FDTD 小时数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>紧凑模型（TCC + 薄屏 / 校准过的 M3D 修正 + 胶核）支撑全芯片与 DTCO。</li><li>严格电磁（FDTD、RCWA）校准近场与热区，不替代每晚的前向。</li><li>Wong 给出 Hopkins 可计算核；Erdmann 给出高 NA 下何时必须离开纯 Kirchhoff。</li><li>模型分层失败时，OPC 会把阴影修进错误的边。</li><li>刻蚀转印下一课，本课停在空中像进入胶之前。</li><li>出处：Wong 投影成像教材；Erdmann 严格掩模与紧凑模型公开文献。</li></ul>',12))])}const _=i(c,[["render",d]]);export{u as __pageData,_ as default};
